export default function ({ posts, rows, previous, base }) {
  const index = (previous?.index ?? -1) + 1;
  if (!Array.isArray(posts) || !Array.isArray(rows)) throw Error("Invalid posts or sheet");
  const p = posts[index];
  if (!p)
    return {
      state: { index },
      more: false,
      skip: true,
      id: 1,
      url: "https://example.invalid",
      post: {},
    };
  const id = Number(p.id);
  if (!Number.isSafeInteger(id) || id < 1) throw Error("Invalid post ID");
  const header = rows[0] || [],
    col = header.indexOf("post_id");
  if (col < 0) throw Error("Missing post_id sheet column");
  const skip = rows.slice(1).some((r) => String(r[col]) === String(id));
  const root = String(base).replace(/\/$/, "");
  if (!/^https:\/\//.test(root)) throw Error("Configure HTTPS site URL");
  return {
    state: { index },
    more: true,
    skip,
    id,
    url: root + "/wp-json/wp/v2/posts/" + id + "?context=edit",
    post: p,
  };
}

