export default function ({ body, id }) {
  if (
    !body ||
    body.id !== id ||
    typeof body.content?.raw !== "string" ||
    typeof body.content?.rendered !== "string" ||
    typeof body.excerpt?.rendered !== "string"
  )
    throw Error("Missing edit-context post fields");
  const text = body.content.rendered
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) throw Error("Empty post");
  return { post: body, text };
}

