export default function ({ answer, post, base }) {
  let x;
  try {
    x = JSON.parse(answer);
  } catch {
    throw Error("Invalid summary JSON");
  }
  if (
    !Array.isArray(x.points) ||
    x.points.length !== 4 ||
    x.points.some((s) => typeof s !== "string" || !s.trim()) ||
    typeof x.label !== "string" ||
    !x.label.trim()
  )
    throw Error("Expected four points and translated label");
  const esc = (s) =>
    s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  const summary =
    '<!-- wp:html --><div class="wp-block-group has-background" style="background-color:#f8faff; border-radius:4px; padding:10px;"><p style="font-style:normal; font-weight:1000; font-size:1.1em; margin:0 0 10px 0;"><strong>✨ ' +
    esc(x.label) +
    "</strong> :</p>" +
    x.points.map((s) => "<li>" + esc(s) + "</li>").join("") +
    '</div><!-- /wp:html --><!-- wp:separator --><hr class="wp-block-separator has-alpha-channel-opacity"/><!-- /wp:separator -->';
  return {
    summary,
    content: summary + " " + post.content.raw,
    excerpt: post.excerpt.rendered,
    postId: post.id,
    values: [
      [
        String(post.id),
        summary,
        post.link || "",
        String(base).replace(/\/$/, "") + "/wp-admin/post.php?post=" + post.id + "&action=edit",
        new Date().toISOString(),
      ],
    ],
    notice:
      "📄 New WordPress Post Updated with AI Summary: " +
      (post.title?.rendered || "") +
      " " +
      (post.link || "") +
      " (ID " +
      post.id +
      ")",
  };
}

