export default async function ({ id, phase }, ctx) {
  const key = "wp-summary:" + id + ":" + phase;
  if (await ctx.state.get(key))
    throw Error("Prior " + phase + " attempt needs reconciliation for post " + id);
  await ctx.state.set(key, { status: "pending" });
  return { id };
}

