export default async function ({ id, phase, receipt }, ctx) {
  if (!receipt || (phase === "wordpress" && receipt.id !== id))
    throw Error("Invalid " + phase + " receipt");
  await ctx.state.set("wp-summary:" + id + ":" + phase, { status: "done" });
  return { id };
}

